<template>
  <label class="ln-select-field"><span v-if="label" class="ln-select-field__label">{{label}}</span><LnPopover align="start" @update:open="onOpen">
    <template #trigger><button class="ln-select__trigger ln-focus-ring" type="button" :disabled="disabled"><span v-if="selected?.color" class="ln-select__dot" :style="{background:selected.color}"/><span :class="{'is-placeholder':!selected}">{{selected?.label||placeholder}}</span><span class="ln-select__chevron">⌄</span></button></template>
    <template #default="{close}"><div class="ln-select__panel"><input v-if="searchable" ref="searchInput" v-model="query" class="ln-select__search" placeholder="搜索…"/><div class="ln-select__options"><button v-if="clearable && modelValue" class="ln-select__option is-clear" type="button" @click="clear(close)"><span>×</span><span><b>清除选择</b></span></button><button v-for="option in filtered" :key="option.value" class="ln-select__option" :class="{'is-selected':option.value===modelValue}" type="button" :disabled="option.disabled" @click="choose(option,close)"><span v-if="option.color" class="ln-select__dot" :style="{background:option.color}"/><span><b>{{option.label}}</b><small v-if="option.description">{{option.description}}</small></span><i v-if="option.value===modelValue">✓</i></button><div v-if="!filtered.length" class="ln-select__empty">没有匹配项</div></div></div></template>
  </LnPopover></label>
</template>
<script setup lang="ts">
import { computed,nextTick,ref } from 'vue'; import LnPopover from './LnPopover.vue'; import type {LnOption} from './types'
const props=withDefaults(defineProps<{modelValue?:string;options:LnOption[];label?:string;placeholder?:string;searchable?:boolean;disabled?:boolean;clearable?:boolean}>(),{placeholder:'请选择'})
const emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'change',option?:LnOption):void}>(); const query=ref('');const searchInput=ref<HTMLInputElement>();const selected=computed(()=>props.options.find(o=>o.value===props.modelValue));const filtered=computed(()=>{const q=query.value.trim().toLowerCase();return q?props.options.filter(o=>(o.label+o.description).toLowerCase().includes(q)):props.options})
function choose(option:LnOption,close:()=>void){if(option.disabled)return;emit('update:modelValue',option.value);emit('change',option);close()};function clear(close:()=>void){emit('update:modelValue','');emit('change');close()}function onOpen(open:boolean){if(open&&props.searchable)nextTick(()=>searchInput.value?.focus());else query.value=''}
</script>
<style scoped lang="scss">
.ln-select-field{display:grid;gap:6px;font-family:var(--ln-font)}.ln-select-field__label{font-size:12px;font-weight:540}.ln-select__trigger{min-width:150px;height:var(--ln-control-md);padding:0 9px;display:flex;align-items:center;gap:7px;border:1px solid var(--ln-border-strong);border-radius:var(--ln-radius-md);background:var(--ln-surface);color:var(--ln-text);font:13px var(--ln-font);cursor:pointer;&:hover{background:var(--ln-surface-hover)}.is-placeholder{color:var(--ln-text-tertiary)}}.ln-select__chevron{margin-left:auto;color:var(--ln-text-tertiary)}.ln-select__dot{width:8px;height:8px;border-radius:50%;flex:0 0 auto}.ln-select__panel{width:250px}.ln-select__search{width:100%;height:30px;margin-bottom:5px;padding:0 8px;border:1px solid var(--ln-border);border-radius:5px;outline:0;font:12px var(--ln-font);&:focus{border-color:var(--ln-accent)}}.ln-select__options{max-height:250px;overflow:auto;display:grid;gap:2px}.ln-select__option{min-height:34px;padding:6px 8px;display:flex;align-items:center;gap:8px;border:0;border-radius:5px;background:transparent;color:var(--ln-text);text-align:left;cursor:pointer;&:hover,&.is-selected{background:var(--ln-surface-hover)}&:disabled{opacity:.4}&.is-clear{margin-bottom:3px;border-bottom:1px solid var(--ln-border);border-radius:0;color:var(--ln-text-secondary)}span:nth-child(2){display:grid;gap:2px}b{font-size:12px;font-weight:520}small{color:var(--ln-text-tertiary);font-size:10px}i{margin-left:auto;color:var(--ln-accent);font-style:normal}}.ln-select__empty{padding:18px;text-align:center;color:var(--ln-text-tertiary);font-size:11px}
</style>
